"""Readonly initial imaging parse-failure boundary checks, no imager calls."""
import json
import sys
from hashlib import sha256
from pathlib import Path

import numpy as np
from casacore.tables import table

checks=[]
def check(name,condition):checks.append({"name":name,"pass":bool(condition)})
def digest(path):
    path=Path(path);h=sha256()
    for p in sorted(path.rglob("*")):
        if p.is_file() and p.name!="table.lock":
            h.update(str(p.relative_to(path)).encode())
            with p.open("rb") as s:
                for b in iter(lambda:s.read(1024**2),b""):h.update(b)
    return h.hexdigest()
def npz(path):
    with np.load(path,allow_pickle=False) as a:return {k:a[k] for k in a.files}
def main():
    root=Path(sys.argv[1]);config=json.loads((root/"imaging-config.json").read_text())
    label="unit-compact";log=root/"checkpoints"/(label+"-wsclean.log")
    check("firstjob rejectedlegacy datacolumn", "Unknown parameter: datacolumn" in log.read_text())
    check("no successful result",not (root/"result.json").exists())
    check("no FITS produced",not list((root/"images").glob("*.fits")))
    written=npz(root/"checkpoints"/(label+"-written.npz"));before=npz(root/"backups"/(label+"-before.npz"))
    source=Path(config["sources"]["response"])/"clean"
    state=npz(source/"state.npz");manifest=json.loads((source/"manifest.json").read_text())
    check("TEST9169 support exact",np.array_equal(written["support"],state["test"]) and int(written["support"].sum())==9169)
    check("protectedoriginal FLAG/FLAG_ROW",not np.any(state["original_flags"] & ~written["FLAG"]) and not np.any(state["original_rows"] & ~written["FLAG_ROW"]))
    with table(str(root/"response-diagnostic.ms"),readonly=True,ack=False,lockoptions="autonoread") as work,table(str(root/"backups/response-input.ms"),readonly=True,ack=False,lockoptions="autonoread") as original,table(str(source/"original.ms"),readonly=True,ack=False,lockoptions="autonoread") as raw:
        for key in ("DATA",manifest["model_column"],"WEIGHT","WEIGHT_SPECTRUM","SIGMA","SIGMA_SPECTRUM"):
            if key in original.colnames():check("unchangedcopiednative "+key,np.array_equal(work.getcol(key),original.getcol(key),equal_nan=True))
        for key in ("FLAG","FLAG_ROW","CORRECTED_DATA"):check("exactfailedcheckpoint "+key,np.array_equal(work.getcol(key),written[key]))
        for key in ("FLAG","FLAG_ROW"):check("exclusiveinitialpreviousbackup "+key,np.array_equal(before[key],original.getcol(key)))
        check("actualoriginalFLAG exactstate",np.array_equal(raw.getcol("FLAG"),state["original_flags"]))
        check("actualoriginalFLAG_ROW exactstate",np.array_equal(raw.getcol("FLAG_ROW"),state["original_rows"]))
        check("original+copiedactiveweights exactstate",np.array_equal(raw.getcol("WEIGHT_SPECTRUM"),state["weights"]) and np.array_equal(work.getcol("WEIGHT_SPECTRUM"),state["weights"]))
        check("no MODEL_DATA append","MODEL_DATA" not in work.colnames() or "MODEL_DATA" in original.colnames())
    check("originalcopydigest preserved",digest(source/"original.ms")==manifest["original_copy_digest"])
    for role,path in config["sources"].items():check("sourcewhole digest "+role,digest(path)==config["source_hashes"][role])
    command_path=root/"checkpoints"/(label+"-command.json")
    result={"status":"PASS" if all(c["pass"] for c in checks) else "FAIL","checks_count":len(checks),"checks":checks,"failure":"pinned WSClean3.6 rejects legacy datacolumn before inversion","completed_inversions":0,"failed_attempts":1,"source_config_sha256":sha256((root/"imaging-config.json").read_bytes()).hexdigest(),"log_sha256":sha256(log.read_bytes()).hexdigest(),"command_sha256":sha256(command_path.read_bytes()).hexdigest(),"command":json.loads(command_path.read_text()),"audit_program_sha256":sha256(Path(__file__).read_bytes()).hexdigest(),"audit_program":Path(__file__).read_text(),"measurement_reruns_or_source_writes":False}
    print(json.dumps(result,allow_nan=False))
if __name__=="__main__":main()
